use super::{LineEnding,TextEncoding};use crate::types::LoadedFile;use crate::Result;use std::fs::{self,OpenOptions};use std::io::{self,Write};use std::path::Path;use std::time::{SystemTime,UNIX_EPOCH};
#[derive(Debug,Default,Clone,Copy)]pub struct FileManager;
impl FileManager{pub fn load_file(path:impl AsRef<Path>)->Result<LoadedFile>{let path=path.as_ref().to_path_buf();let bytes=fs::read(&path)?;let(encoding,bom,_)=TextEncoding::detect(&bytes);let decoded=encoding.decode(&bytes)?;let ending=LineEnding::detect(decoded.as_bytes());Ok(LoadedFile{path,text:LineEnding::normalize_to_lf(&decoded),encoding,line_ending:ending,had_bom:bom})}pub fn save_file(path:impl AsRef<Path>,text:&str,encoding:TextEncoding,ending:LineEnding)->Result<()>{Self::save_file_with_bom(path,text,encoding,ending,false)}pub fn save_file_with_bom(path:impl AsRef<Path>,text:&str,encoding:TextEncoding,ending:LineEnding,bom:bool)->Result<()>{let path=path.as_ref();if let Some(p)=path.parent().filter(|p|!p.as_os_str().is_empty()){fs::create_dir_all(p)?}atomic_write(path,&encoding.encode(&ending.apply(text),bom))}pub fn save_extracted_text(path:impl AsRef<Path>,text:&str)->Result<()>{Self::save_file(path,text,TextEncoding::Utf8,LineEnding::Lf)}}
fn atomic_write(path:&Path,bytes:&[u8])->Result<()>{let stamp=SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default().as_nanos();let name=path.file_name().and_then(|n|n.to_str()).unwrap_or("document");let temp=path.with_file_name(format!(".{name}.{stamp}.notepad-tmp"));let result=(||->io::Result<()>{let mut f=OpenOptions::new().create_new(true).write(true).open(&temp)?;f.write_all(bytes)?;f.sync_all()?;drop(f);replace(&temp,path)})();if result.is_err(){let _=fs::remove_file(&temp);}result.map_err(Into::into)}
#[cfg(not(windows))]fn replace(temp:&Path,path:&Path)->io::Result<()>{fs::rename(temp,path)}
#[cfg(windows)]fn replace(temp:&Path,path:&Path)->io::Result<()>{use std::os::windows::ffi::OsStrExt;extern "system"{fn MoveFileExW(a:*const u16,b:*const u16,flags:u32)->i32;}let wide=|p:&Path|p.as_os_str().encode_wide().chain(std::iter::once(0)).collect::<Vec<_>>();let a=wide(temp);let b=wide(path);if unsafe{MoveFileExW(a.as_ptr(),b.as_ptr(),1)}!=0{Ok(())}else{Err(io::Error::last_os_error())}}
